//! Products and squares of a few limbs in registers, for the first steps of the doublings of the
//! Fibonacci and Lucas numbers and of the Lucas sequences. Generated by `small.py`; do not edit.
//!
//! The kernels of the multiplication are rows of limb products in inline assembly: at one to
//! eight limbs their passes' setup costs as much as the products themselves (a product of five
//! limbs by five took 52 cycles on an Apple M4 Max, about two a limb product, and a square of three
//! 17). Here the length is a constant, the operands are read into locals and every column of the
//! product is summed in a three-limb accumulator (Comba's order), the code written out in full: a
//! limb product is a `mul`, a `umulh` and three additions; a square sums the products of two
//! different limbs once, then doubles them and adds the squares of the limbs.

use super::super::mul::basecase;

/// The longest operands taken here; longer ones go to the multiplication's kernels.
pub(super) const MAX: usize = 8;

/// Adds `x y` to the column's sum `acc + top 2^128`.
#[inline(always)]
fn mac(acc: &mut u128, top: &mut u64, x: u64, y: u64) {
    let (s, o) = acc.overflowing_add(u128::from(x) * u128::from(y));
    *acc = s;
    *top += u64::from(o);
}

/// Sets limbs `k` and `k + 1` of `s` to the two doubled limbs `lo` and `hi` plus `x^2` and the
/// carry, which it updates.
#[inline(always)]
fn diagonal<const L: usize>(s: &mut [u64; L], k: usize, lo: u64, hi: u64, x: u64, carry: &mut u64) {
    let d = u128::from(lo) | (u128::from(hi) << 64);
    let (v, o1) = d.overflowing_add(u128::from(x) * u128::from(x));
    let (v, o2) = v.overflowing_add(u128::from(*carry));
    s[k] = v as u64;
    s[k + 1] = (v >> 64) as u64;
    *carry = u64::from(o1) + u64::from(o2);
}

/// The column's low limb, and the sum shifted down by a limb for the next column.
#[inline(always)]
fn next(acc: &mut u128, top: &mut u64) -> u64 {
    let low = *acc as u64;
    *acc = (*acc >> 64) | (u128::from(*top) << 64);
    *top = 0;
    low
}

/// Sets the `2n` limbs at `r` to the square of the `n` limbs at `a`: here up to [`MAX`] limbs, and
/// by the schoolbook kernel beyond.
///
/// # Safety
///
/// `n >= 1`; the limbs at `a` must be valid for reads and those at `r` for writes, apart.
#[inline(never)]
pub(super) unsafe fn sqr(r: *mut u64, a: *const u64, n: usize) {
    // SAFETY: forwarded.
    unsafe {
        match n {
            1 => sqr_1(r, a),
            2 => sqr_2(r, a),
            3 => sqr_3(r, a),
            4 => sqr_4(r, a),
            5 => sqr_5(r, a),
            6 => sqr_6(r, a),
            7 => sqr_7(r, a),
            8 => sqr_8(r, a),
            _ => basecase::sqr(r, a, n),
        }
    }
}

/// Sets the `2n` limbs at `r` to the product of the `n` limbs at `a` and at `b`: here up to [`MAX`]
/// limbs, and by the schoolbook kernel beyond.
///
/// # Safety
///
/// `n >= 1`; the limbs at `a` and `b` must be valid for reads and those at `r` for writes, `r`
/// apart from both.
#[inline(never)]
pub(super) unsafe fn mul(r: *mut u64, a: *const u64, b: *const u64, n: usize) {
    // SAFETY: forwarded.
    unsafe {
        match n {
            1 => mul_1(r, a, b),
            2 => mul_2(r, a, b),
            3 => mul_3(r, a, b),
            4 => mul_4(r, a, b),
            5 => mul_5(r, a, b),
            6 => mul_6(r, a, b),
            7 => mul_7(r, a, b),
            8 => mul_8(r, a, b),
            _ => basecase::mul(r, a, b, n),
        }
    }
}

/// Sets the 2 limbs at `r` to the product of the 1 limbs at `a` and at `b`.
///
/// # Safety
///
/// The limbs at `a` and `b` must be valid for reads and those at `r` for writes; `r` may be
/// either, as the operands are read before anything is written.
#[inline(always)]
pub(super) unsafe fn mul_1(r: *mut u64, a: *const u64, b: *const u64) {
    // SAFETY: as the caller guarantees.
    let (a, b) = unsafe { (a.cast::<[u64; 1]>().read(), b.cast::<[u64; 1]>().read()) };
    let (mut acc, mut top) = (0u128, 0u64);
    let mut s = [0u64; 2];
    mac(&mut acc, &mut top, a[0], b[0]);
    s[0] = next(&mut acc, &mut top);
    s[1] = acc as u64;
    // SAFETY: as the caller guarantees.
    unsafe { r.cast::<[u64; 2]>().write(s) };
}

