unsafe fn mul_hi_3(r: *mut u64, a: *const u64, b: *const u64) {
    let mut s = [0u64; 6];
    // SAFETY: as the caller guarantees; the product is formed in `s` first.
    unsafe {
        mul_3(s.as_mut_ptr(), a, b);
        let hi: [u64; 3] = core::array::from_fn(|i| s[i + 2]);
        r.cast::<[u64; 3]>().write(hi);
    }
}

