/// Sets the `N` limbs at `r` to limbs `N - 1` to `2N - 2` of the product of the `N` limbs at `a`
/// and at `b`, `1 <= N <= MAX`: a fixed-point product with `N - 1` limbs of fraction.
///
/// # Safety
///
/// The limbs at `a` and `b` must be valid for reads and those at `r` for writes; `r` may be
/// either.
#[inline(always)]
pub(super) unsafe fn mul_hi<const N: usize>(r: *mut u64, a: *const u64, b: *const u64) {
    // SAFETY: forwarded; `N` is a constant, which picks one arm.
    unsafe {
        match N {
            1 => mul_hi_1(r, a, b),
            2 => mul_hi_2(r, a, b),
            3 => mul_hi_3(r, a, b),
            4 => mul_hi_4(r, a, b),
            5 => mul_hi_5(r, a, b),
            6 => mul_hi_6(r, a, b),
            7 => mul_hi_7(r, a, b),
            8 => mul_hi_8(r, a, b),
            _ => unreachable!("a fixed-point product of more than MAX limbs"),
        }
    }
}

/// Sets the `N` limbs at `r` to limbs `N - 1` to `2N - 2` of the square of the `N` limbs at `a`,
/// `1 <= N <= MAX`.
///
/// # Safety
///
/// As for [`mul_hi`].
#[inline(always)]
pub(super) unsafe fn sqr_hi<const N: usize>(r: *mut u64, a: *const u64) {
    // SAFETY: as for `mul_hi`.
    unsafe {
        match N {
            1 => sqr_hi_1(r, a),
            2 => sqr_hi_2(r, a),
            3 => sqr_hi_3(r, a),
            4 => sqr_hi_4(r, a),
            5 => sqr_hi_5(r, a),
            6 => sqr_hi_6(r, a),
            7 => sqr_hi_7(r, a),
            8 => sqr_hi_8(r, a),
            _ => unreachable!("a fixed-point square of more than MAX limbs"),
        }
    }
}
